// rule (peak hours, membership discounts) is a new class, not an edit to
// ParkingLot. Multi-currency support was deliberately left out of scope.

// VENDING MACHINE - LOW LEVEL DESIGN
//
// Design patterns:
// 1. State Pattern -> manages machine states and prevents invalid operations.
// 2. Strategy Pattern -> supports multiple payment methods.
// 3. Composition -> VendingMachine owns Inventory.

// --------------------
// DOMAIN MODELS
// --------------------

class Item {
  constructor(
    public readonly id: string,
    public readonly name: string,
    public readonly price: number
  ) {}
}

class ItemSlot {
  constructor(
    public readonly item: Item,
    private quantity: number
  ) {}

  isAvailable(): boolean {
    return this.quantity > 0;
  }

  dispense(): void {
    if (!this.isAvailable()) {
      throw new Error("Item is out of stock");
    }

    this.quantity--;
  }

  getQuantity(): number {
    return this.quantity;
  }
}


// --------------------
// INVENTORY
// --------------------

class Inventory {
  private slots = new Map<string, ItemSlot>();

  addItem(item: Item, quantity: number): void {
    this.slots.set(item.id, new ItemSlot(item, quantity));
  }

  getItem(itemId: string): Item | null {
    const slot = this.slots.get(itemId);

    if (!slot || !slot.isAvailable()) {
      return null;
    }

    return slot.item;
  }

  isAvailable(itemId: string): boolean {
    return this.slots.get(itemId)?.isAvailable() ?? false;
  }

  dispense(itemId: string): void {
    const slot = this.slots.get(itemId);

    if (!slot || !slot.isAvailable()) {
      throw new Error("Item is out of stock");
    }

    slot.dispense();
  }
}


// --------------------
// PAYMENT STRATEGY
// --------------------

interface PaymentMethod {
  pay(amount: number): PaymentResult;
}

interface PaymentResult {
  success: boolean;
  amountPaid: number;
  change: number;
  message?: string;
}


// Cash supports overpayment and change.
class CashPayment implements PaymentMethod {
  constructor(private readonly cashAmount: number) {}

  pay(amount: number): PaymentResult {
    if (this.cashAmount < amount) {
      return {
        success: false,
        amountPaid: this.cashAmount,
        change: 0,
        message: "Insufficient cash"
      };
    }

    return {
      success: true,
      amountPaid: this.cashAmount,
      change: this.cashAmount - amount
    };
  }
}


// Card payment normally charges the exact amount.
class CardPayment implements PaymentMethod {
  pay(amount: number): PaymentResult {
    // In production this would call a payment gateway.
    const paymentSuccessful = true;

    if (!paymentSuccessful) {
      return {
        success: false,
        amountPaid: 0,
        change: 0,
        message: "Card payment failed"
      };
    }

    return {
      success: true,
      amountPaid: amount,
      change: 0
    };
  }
}


// Easy to add later without modifying VendingMachine.
class UPIPayment implements PaymentMethod {
  pay(amount: number): PaymentResult {
    const paymentSuccessful = true;

    return {
      success: paymentSuccessful,
      amountPaid: paymentSuccessful ? amount : 0,
      change: 0,
      message: paymentSuccessful ? undefined : "UPI payment failed"
    };
  }
}


// --------------------
// STATE PATTERN
// --------------------

interface VendingMachineState {
  selectItem(machine: VendingMachine, itemId: string): void;
  makePayment(machine: VendingMachine, payment: PaymentMethod): void;
  cancel(machine: VendingMachine): void;
}


// Initial state.
class IdleState implements VendingMachineState {
  selectItem(machine: VendingMachine, itemId: string): void {
    const item = machine.inventory.getItem(itemId);

    if (!item) {
      console.log("Item is out of stock.");
      return;
    }

    machine.selectedItem = item;
    machine.setState(new ItemSelectedState());

    console.log(`Selected ${item.name}. Price: ${item.price}`);
  }

  makePayment(): void {
    console.log("Please select an item first.");
  }

  cancel(): void {
    console.log("Nothing to cancel.");
  }
}


// Item selected, waiting for payment.
class ItemSelectedState implements VendingMachineState {
  selectItem(): void {
    console.log("An item is already selected.");
  }

  makePayment(machine: VendingMachine, payment: PaymentMethod): void {
    machine.setState(new PaymentPendingState());

    machine.processPayment(payment);
  }

  cancel(machine: VendingMachine): void {
    machine.reset();
    console.log("Transaction cancelled.");
  }
}


// Payment is being processed.
class PaymentPendingState implements VendingMachineState {
  selectItem(): void {
    console.log("Payment is currently being processed.");
  }

  makePayment(): void {
    console.log("Payment is already being processed.");
  }

  cancel(machine: VendingMachine): void {
    machine.reset();
    console.log("Transaction cancelled/refunded.");
  }
}


// --------------------
// VENDING MACHINE
// --------------------

class VendingMachine {
  public readonly inventory: Inventory;

  private state: VendingMachineState;
  public selectedItem: Item | null = null;

  constructor(inventory: Inventory) {
    this.inventory = inventory;
    this.state = new IdleState();
  }

  setState(state: VendingMachineState): void {
    this.state = state;
  }

  selectItem(itemId: string): void {
    this.state.selectItem(this, itemId);
  }

  makePayment(payment: PaymentMethod): void {
    this.state.makePayment(this, payment);
  }

  cancel(): void {
    this.state.cancel(this);
  }

  processPayment(payment: PaymentMethod): void {
    if (!this.selectedItem) {
      this.reset();
      return;
    }

    const result = payment.pay(this.selectedItem.price);

    if (!result.success) {
      console.log(result.message ?? "Payment failed");
      this.reset();
      return;
    }

    // Important: dispense only after successful payment.
    try {
      this.inventory.dispense(this.selectedItem.id);

      console.log(`Dispensing ${this.selectedItem.name}`);

      if (result.change > 0) {
        console.log(`Returning change: ${result.change}`);
      }

      this.reset();

    } catch (error) {
      // In production, payment should be refunded if
      // dispensing fails.
      console.log("Dispensing failed. Refund required.");
      this.reset();
    }
  }

  reset(): void {
    this.selectedItem = null;
    this.state = new IdleState();
  }
}


// --------------------
// EXAMPLE USAGE
// --------------------

const inventory = new Inventory();

inventory.addItem(
  new Item("A1", "Coke", 40),
  5
);

inventory.addItem(
  new Item("B1", "Chips", 30),
  2
);

const machine = new VendingMachine(inventory);

// Successful cash payment
machine.selectItem("A1");
machine.makePayment(new CashPayment(50));
// -> Dispenses Coke
// -> Returns 10 change


// Successful card payment
machine.selectItem("B1");
machine.makePayment(new CardPayment());


// Out of stock
machine.selectItem("C1");
// -> "Item is out of stock"


// Insufficient payment
machine.selectItem("A1");
machine.makePayment(new CashPayment(20));
// -> Payment rejected/refunded


// --------------------
// DESIGN TRADE-OFFS
// --------------------

/*
1. STATE PATTERN

The vending machine behaves differently depending on its state.
For example:
- Cannot pay before selecting an item.
- Cannot select another item while payment is processing.
- Cannot dispense before successful payment.

Using states avoids a large collection of if/else conditions
inside VendingMachine.

2. STRATEGY PATTERN

PaymentMethod abstracts payment processing.

CashPayment, CardPayment and UPIPayment can have different
implementations without changing VendingMachine.

Adding a new payment method only requires a new strategy.

3. SINGLE RESPONSIBILITY

Inventory manages stock.
PaymentMethod manages payment.
VendingMachine coordinates the transaction.
States control valid operations.

4. FAILURE HANDLING

An out-of-stock item never enters the payment flow.

Insufficient/failed payment resets the transaction.

If payment succeeds but dispensing fails, the system should
refund the payment. In a production system, payment and
dispensing would use a transaction/reservation mechanism to
guarantee consistency.

5. EXTENSIBILITY

The design can later support:
- UPI
- Wallets
- NFC
- Multiple item categories
- Change management
- Admin restocking
- Transaction history
- Payment gateway integration

without significantly modifying the core VendingMachine class.
*/

